     (Z_to_bv 64 (s - 56)) (word_to_le_bytes 8 (Z_to_bv 64 0x78e68)))
     (Z_to_bv 64 (s - 64)) (word_to_le_bytes 8 (Z_to_bv 64 pix1)))
